import{_ as t,o as l,c as r,a2 as o}from"./chunks/framework.BV21bweQ.js";const q=JSON.parse('{"title":"拉斯塔","description":"","frontmatter":{},"headers":[],"relativePath":"中层/人物/拉斯塔.md","filePath":"中层/人物/拉斯塔.md","lastUpdated":1787066340000}'),i={name:"中层/人物/拉斯塔.md"};function n(s,a,e,h,g,u){return l(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="拉斯塔" tabindex="-1">拉斯塔 <a class="header-anchor" href="#拉斯塔" aria-label="Permalink to &quot;拉斯塔&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><ul><li><strong>名称含义</strong>：谐音&quot;last&quot;，源自老设定&quot;她是最后一个狐族&quot;（该设定已抛弃，因叫习惯保留名字）</li><li><strong>称号</strong>：四代变化神（与维斯塔共享神权）</li><li><strong>种族</strong>：狐族</li><li><strong>性别</strong>：雌性（狐族全为雌性）</li><li><strong>年龄</strong>：青少年，孤儿院中年龄偏大的孩子</li><li><strong>当前身份</strong>：红星孤儿院孤儿，故事女主，四代变化神载体</li><li><strong>神权状态</strong>：与维斯塔（三代变化神）共享变化神权（双载体悖论）</li></ul><h2 id="外貌特征与形态" tabindex="-1">外貌特征与形态 <a class="header-anchor" href="#外貌特征与形态" aria-label="Permalink to &quot;外貌特征与形态&quot;">​</a></h2><h3 id="狐族特征" tabindex="-1">狐族特征 <a class="header-anchor" href="#狐族特征" aria-label="Permalink to &quot;狐族特征&quot;">​</a></h3><ul><li><strong>种族外观</strong>：典型的狐族外貌，具有狐耳和狐尾</li><li><strong>毛色</strong>：橙黄与白，为狐族常见毛色</li><li><strong>体型</strong>：少女体型，符合青少年特征</li><li><strong>表情特点</strong>：阳光开朗，带有几分机敏和灵动</li></ul><h3 id="孤儿院形象" tabindex="-1">孤儿院形象 <a class="header-anchor" href="#孤儿院形象" aria-label="Permalink to &quot;孤儿院形象&quot;">​</a></h3><ul><li><strong>服装</strong>：喜欢穿着适合外出的探险装</li><li><strong>日常状态</strong>：看起来像是普通的孤儿院青少年</li><li><strong>气质</strong>：兼具少女的天真和狐族的机敏，是孤儿院孩子的领头者</li></ul><h3 id="神明特征" tabindex="-1">神明特征 <a class="header-anchor" href="#神明特征" aria-label="Permalink to &quot;神明特征&quot;">​</a></h3><ul><li><strong>神环显现</strong>：在特定情况下可能显现变化神环</li><li><strong>神权特征</strong>：因魔法本身就是逸散的变化神权，故拉斯塔对任何魔法都是一学就会，并毫无副作用</li><li><strong>状态变化</strong>：神权显现时眼瞳会发光</li><li><strong>思维灵活</strong>：变化神权潜移默化的影响，使其思维也更灵活多变</li><li><strong>学习迅速</strong>：变化神权潜移默化的影响，使其学习新知识的速度极其迅速</li></ul><h2 id="背景历史" tabindex="-1">背景历史 <a class="header-anchor" href="#背景历史" aria-label="Permalink to &quot;背景历史&quot;">​</a></h2><h3 id="童年与孤儿背景" tabindex="-1">童年与孤儿背景 <a class="header-anchor" href="#童年与孤儿背景" aria-label="Permalink to &quot;童年与孤儿背景&quot;">​</a></h3><ul><li><strong>孤儿身份</strong>：狮族战争后成为孤儿，被院长接入红星孤儿院</li><li><strong>孤儿院生活</strong>：在红星孤儿院成长，年龄在孤儿院里偏大</li><li><strong>领头角色</strong>：性格开朗，是孤儿院孩子们的领头者</li></ul><h3 id="童年创伤-狮族战争与-龙-的救助" tabindex="-1">童年创伤：狮族战争与&quot;龙&quot;的救助 <a class="header-anchor" href="#童年创伤-狮族战争与-龙-的救助" aria-label="Permalink to &quot;童年创伤：狮族战争与&quot;龙&quot;的救助&quot;">​</a></h3><ul><li><strong>村子被屠戮</strong>：拉斯塔的村子在狮族战争中被狮族仆从族屠戮</li><li><strong>被追捕</strong>：拉斯塔被豺族追兵追捕，危急时刻</li><li><strong>&quot;巨龙&quot;救援</strong>：被&quot;没有尾巴的巨龙&quot;吓走追兵，救下一命</li><li><strong>真相</strong>：该&quot;巨龙&quot;实则是<strong>古斯塔夫（智能空中战斗平台）</strong>，当时正运载着鹿族&quot;环形山计划&quot;的核弹前往狮族首都，救拉斯塔是其执行任务途中的偶然行为</li><li><strong>核心执念</strong>：这一经历成为拉斯塔后续&quot;寻找龙&quot;的核心执念</li></ul><h2 id="人格特质与核心特质" tabindex="-1">人格特质与核心特质 <a class="header-anchor" href="#人格特质与核心特质" aria-label="Permalink to &quot;人格特质与核心特质&quot;">​</a></h2><h3 id="表面形象-喜爱冒险的开朗少女" tabindex="-1">表面形象：喜爱冒险的开朗少女 <a class="header-anchor" href="#表面形象-喜爱冒险的开朗少女" aria-label="Permalink to &quot;表面形象：喜爱冒险的开朗少女&quot;">​</a></h3><ul><li><strong>表面性格</strong>：看似普通的阳光少女，开朗活泼</li><li><strong>冒险渴望</strong>：从小热爱冒险，渴望走出孤儿院</li><li><strong>多次阻拦</strong>：被院长维斯塔以&quot;未完全成年（青少年）&quot;为由多次阻拦外出冒险</li><li><strong>领导特质</strong>：是孤儿院孩子的领头者，具有领导力</li></ul><h3 id="内在危险-不知情的危险存在" tabindex="-1">内在危险：不知情的危险存在 <a class="header-anchor" href="#内在危险-不知情的危险存在" aria-label="Permalink to &quot;内在危险：不知情的危险存在&quot;">​</a></h3><ul><li><strong>表面实力</strong>：看似普通施法者，实力一般</li><li><strong>实际真相</strong>：作为四代变化神<strong>实则极度危险</strong>——自身对真实情况毫不知情</li><li><strong>唯二知情者</strong>：院长维斯塔，与神机是唯二知晓其危险的人</li></ul><h2 id="当前状态与悖论" tabindex="-1">当前状态与悖论 <a class="header-anchor" href="#当前状态与悖论" aria-label="Permalink to &quot;当前状态与悖论&quot;">​</a></h2><h3 id="双载体悖论状态" tabindex="-1">双载体悖论状态 <a class="header-anchor" href="#双载体悖论状态" aria-label="Permalink to &quot;双载体悖论状态&quot;">​</a></h3><ul><li><strong>共享神权</strong>：与维斯塔（三代变化神）共享变化神权</li><li><strong>绑定关系</strong>：呈现维斯塔强则拉斯塔弱、反之亦然的绑定关系</li><li><strong>悖论影响</strong>：当前维斯塔占据绝对主导，拉斯塔处于弱势状态</li></ul><h3 id="能力状态" tabindex="-1">能力状态 <a class="header-anchor" href="#能力状态" aria-label="Permalink to &quot;能力状态&quot;">​</a></h3><ul><li><strong>变化神权</strong>：拥有变化神权的基本权限，但处于共享状态</li><li><strong>使用特点</strong>：完全不知道这是神权，认为其是普通魔法，处于探索学习阶段</li><li><strong>潜力巨大</strong>：具有巨大的发展潜力，但目前仍旧认为其是普通魔法</li></ul><h3 id="现状" tabindex="-1">现状 <a class="header-anchor" href="#现状" aria-label="Permalink to &quot;现状&quot;">​</a></h3><ul><li><strong>表面生活</strong>：红星孤儿院孤儿，过着看似普通的孤儿院生活</li><li><strong>真实身份</strong>：第四代变化神权载体（第四代变化神）</li><li><strong>居住地</strong>：红星孤儿院</li></ul><h2 id="关键关系" tabindex="-1">关键关系 <a class="header-anchor" href="#关键关系" aria-label="Permalink to &quot;关键关系&quot;">​</a></h2><h3 id="与维斯塔-双监护关系" tabindex="-1">与维斯塔：双监护关系 <a class="header-anchor" href="#与维斯塔-双监护关系" aria-label="Permalink to &quot;与维斯塔：双监护关系&quot;">​</a></h3><ul><li><strong>监护教导</strong>：维斯塔作为院长是拉斯塔的监护人，打着魔法知识的幌子教导其神权使用知识</li><li><strong>保护关系</strong>：维斯塔是唯一知晓拉斯塔危险真相的人，出于保护目的限制其外出</li></ul><h3 id="与-龙-古斯塔夫-救命恩-人" tabindex="-1">与&quot;龙&quot;（古斯塔夫）：救命恩&quot;人&quot; <a class="header-anchor" href="#与-龙-古斯塔夫-救命恩-人" aria-label="Permalink to &quot;与&quot;龙&quot;（古斯塔夫）：救命恩&quot;人&quot;&quot;">​</a></h3><ul><li><strong>童年救助</strong>：童年时被古斯塔夫（伪装成&quot;龙&quot;的智能空中战斗平台）救过</li><li><strong>深刻印记</strong>：留下深刻的记忆和情感印记</li><li><strong>寻找动机</strong>：成为寻找&quot;龙&quot;的强烈动机和核心执念</li><li><strong>真相未知</strong>：拉斯塔不知道&quot;龙&quot;的真相是智能空中战斗平台</li></ul><h3 id="与狼族少年-毁灭神权载体" tabindex="-1">与狼族少年（毁灭神权载体） <a class="header-anchor" href="#与狼族少年-毁灭神权载体" aria-label="Permalink to &quot;与狼族少年（毁灭神权载体）&quot;">​</a></h3><ul><li><strong>孤儿院同伴</strong>：同为红星孤儿院的孤儿</li><li><strong>日常互动</strong>：有日常的互动和交流</li><li><strong>神权关联</strong>：毁灭神与变化神的潜在关联，是神机计划的一部分</li><li><strong>同伴感情</strong>：建立了同伴感情，是冒险路途上的伙伴</li></ul><h3 id="与其他孤儿院孤儿" tabindex="-1">与其他孤儿院孤儿 <a class="header-anchor" href="#与其他孤儿院孤儿" aria-label="Permalink to &quot;与其他孤儿院孤儿&quot;">​</a></h3><ul><li><strong>领头角色</strong>：是孤儿院孩子们的领头者</li><li><strong>社交网络</strong>：在孤儿院中建立社交关系</li></ul><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../../表层/人物/拉斯塔" class="layer-link" data-layer="表层">拉斯塔（表层档案）</a></li><li><a href="./../../底层/规则/神权体系" class="layer-link" data-layer="底层">神权体系</a></li><li><a href="./维斯塔">维斯塔</a></li><li><a href="./../../表层/种族/狐族" class="layer-link" data-layer="表层">狐族</a></li><li><a href="./古斯塔夫">古斯塔夫</a></li><li><a href="./../世界/神机谋划">神机谋划</a></li></ul><hr>',40)])])}const c=t(i,[["render",n]]);export{q as __pageData,c as default};
